import 'package:flutter/material.dart';
import '../../../core/services/scan_store.dart';
import '../../../core/widgets/common.dart';
class HistoryScreen extends StatelessWidget { const HistoryScreen({super.key}); @override Widget build(BuildContext c){final scans=LocalScanStore().all(); return Scaffold(appBar:AppBar(title:const Text('Scan history')),body:scans.isEmpty?Center(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.history,size:56),const SizedBox(height:14),Text('Your history is empty',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:8),const Text('Completed screenings will show up here.')]))):ListView(padding:const EdgeInsets.all(16),children:[const NoticeBanner(),...scans.map((s)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.spa_outlined)),title:Text(s.prediction),subtitle:Text('${s.date.toLocal().toString().split(' ').first} · ${s.area}'),trailing:Text(s.risk))))]));}}
